 if(key==='animeVoidCustomV1'){if(!plain(value)||value.version!==1||Object.keys(value).length>12)throw Error('Invalid custom settings');const out={version:1};for(const k of ['avatarFrame','profileFrame','effect','bannerMotion','title']){if(typeof value[k]!=='string'||!/^[-a-z0-9]{1,32}$/.test(value[k]))throw Error('Invalid style');out[k]=value[k];}if(!/^#[a-fA-F0-9]{6}$/.test(value.accent)||!Number.isInteger(value.intensity)||value.intensity<0||value.intensity>100||!Number.isInteger(value.speed)||value.speed<5||value.speed>30||typeof value.motion!=='boolean')throw Error('Invalid settings');return {...out,accent:value.accent,intensity:value.intensity,speed:value.speed,motion:value.motion};}
