  if(key==='animeVoidListItems'){if(!plain(value))throw Error('Invalid list snapshots');const entries=Object.entries(value);if(entries.length>30000)throw Error('Too many list items');const out={};for(const[k,v]of entries){if(!ID.test(k))throw Error('Invalid anime ID');const a=catalog([v],strict);if(a.length)out[k]=a[0];}return out;}
